     1→/**
     2→ * FreeWire - 브라우저 실행 엔진 (Node.js 서버사이드 + 브라우저 공용)
     3→ * .free 코드를 파싱 → HTML/CSS/JS 변환 → 실시간 실행
     4→ * WASM 없이 순수 JS로 동작하지만 WASM Bridge 인터페이스 제공
     5→ */
     6→
     7→// ─── FreeLang Light 인라인 파서 ─────────────────────────────────
     8→class FreeLangParser {
     9→  constructor() { this.reset(); }
    10→
    11→  reset() {
    12→    this.props   = {};
    13→    this.style   = '';
    14→    this.script  = '';
    15→    this.markup  = '';
    16→    this.name    = 'Component';
    17→  }
    18→
    19→  parse(code) {
    20→    this.reset();
    21→
    22→    // 컴포넌트 이름 추출
    23→    const nameMatch = code.match(/component\s+(\w+)/);
    24→    if (nameMatch) this.name = nameMatch[1];
    25→
    26→    // 섹션 추출 (중첩 {} 지원)
    27→    this.props  = this._extractProps(code);
    28→    this.style  = this._extractBlock(code, 'style');
    29→    this.script = this._extractBlock(code, 'script');
    30→    this.markup = this._extractBlock(code, 'markup');
    31→
    32→    return this;
    33→  }
    34→
    35→  _extractBlock(code, keyword) {
    36→    const re = new RegExp(`\\b${keyword}\\s*\\{`);
    37→    const m  = re.exec(code);
    38→    if (!m) return '';
    39→    let depth = 1, i = m.index + m[0].length;
    40→    const start = i;
    41→    while (i < code.length && depth > 0) {
    42→      if (code[i] === '{') depth++;
    43→      else if (code[i] === '}') depth--;
    44→      i++;
    45→    }
    46→    return code.slice(start, i - 1).trim();
    47→  }
    48→
    49→  _extractProps(code) {
    50→    const block = this._extractBlock(code, 'props');
    51→    const props = {};
    52→    if (!block) return props;
    53→    const lines = block.split('\n').map(l => l.trim()).filter(Boolean);
    54→    lines.forEach(line => {
    55→      const m = line.match(/^(\w+)\s*:\s*\w+\s*(?:=\s*(.+?))?;?\s*$/);
    56→      if (m) props[m[1]] = (m[2] || '').replace(/['"]/g, '').replace(/;$/, '').trim();
    57→    });
    58→    return props;
    59→  }
    60→}
    61→
    62→// ─── CSS 컴파일러 ────────────────────────────────────────────────
    63→class CSSCompiler {
    64→  compile(styleBlock) {
    65→    if (!styleBlock.trim()) return '';
    66→    return styleBlock
    67→      .replace(/([a-z])([A-Z])/g, '$1-$2')
    68→      .toLowerCase()
    69→      .trim();
    70→  }
    71→}
    72→
    73→// ─── JS 컴파일러 ─────────────────────────────────────────────────
    74→class JSCompiler {
    75→  compile(scriptBlock, componentName) {
    76→    if (!scriptBlock.trim()) return '';
    77→
    78→    const lines = scriptBlock.split('\n').map(l => l.trim()).filter(Boolean);
    79→    const out   = [];
    80→
    81→    out.push(`/* FreeWire: ${componentName} */`); // eslint-disable-line
    82→    out.push('(function(fw) {');
    83→    out.push('  "use strict";');
    84→
    85→    // 상태 변수 추적
    86→    const stateVars = [];
    87→    lines.forEach(line => {
    88→      // state setter 감지: function set_xxx(v) { xxx = v; }
    89→      const setterMatch = line.match(/^function\s+set_(\w+)\(/);
    90→      if (setterMatch) stateVars.push(setterMatch[1]);
    91→
    92→      out.push('  ' + line);
    93→    });
    94→
    95→    // state 변경 시 DOM 업데이트
    96→    out.push('');
    97→    out.push('  // 반응형 DOM 업데이트');
    98→    out.push('  function __fw_update() {');
    99→    out.push('    var els = document.querySelectorAll("[data-fw-bind]");');
   100→    out.push('    els.forEach(function(el) {');
   101→    out.push('      var key = el.getAttribute("data-fw-bind");');
   102→    out.push('      try { el.textContent = eval(key); } catch(e) {}');
   103→    out.push('    });');
   104→    // state setter 오버라이드 (업데이트 자동 트리거)
   105→    stateVars.forEach(v => {
   106→      out.push(`    if (typeof ${v} !== "undefined" && fw.__prev_${v} !== ${v}) {`);
   107→      out.push(`      fw.__prev_${v} = ${v};`);
   108→      out.push('    }');
   109→    });
   110→    out.push('  }');
   111→    out.push('');
   112→
   113→    // setter 오버라이드 (원본 setter 호출 후 __fw_update)
   114→    stateVars.forEach(v => {
   115→      out.push(`  var __orig_set_${v} = typeof set_${v} === "function" ? set_${v} : null;`);
   116→      out.push(`  set_${v} = function(v) { if (__orig_set_${v}) __orig_set_${v}(v); __fw_update(); };`);
   117→    });
   118→
   119→    // 이벤트 바인딩
   120→    out.push('');
   121→    out.push('  document.addEventListener("DOMContentLoaded", function() {');
   122→    out.push('    __fw_update();');
   123→    out.push('    // 버튼 이벤트 자동 바인딩');
   124→    out.push('    document.querySelectorAll("[data-fw-action]").forEach(function(el) {');
   125→    out.push('      var action = el.getAttribute("data-fw-action");');
   126→    out.push('      el.addEventListener("click", function() {');
   127→    out.push('        try { eval(action + "()"); __fw_update(); } catch(e) { console.warn("FW:", e); }');
   128→    out.push('      });');
   129→    out.push('    });');
   130→    out.push('  });');
   131→    out.push('})({});');
   132→
   133→    return out.join('\n');
   134→  }
   135→}
   136→
   137→// ─── HTML 컴파일러 ───────────────────────────────────────────────
   138→class HTMLCompiler {
   139→  compile(markupBlock) {
   140→    if (!markupBlock.trim()) return '';
   141→
   142→    return markupBlock
   143→      .replace(/\bmarkup\s*\{/g, '')
   144→      .replace(/^\s*\}\s*$/gm, '')
   145→      // {{변수}} → data-fw-bind 속성
   146→      .replace(/\{\{(\w+)\}\}/g, '<span data-fw-bind="$1">$1</span>')
   147→      // 버튼 클릭 함수 자동 감지: onclick="xxx()" → data-fw-action
   148→      .replace(/onclick="(\w+)\(\)"/g, 'data-fw-action="$1"')
   149→      .replace(/\n{3,}/g, '\n\n')
   150→      .trim();
   151→  }
   152→}
   153→
   154→// ─── 메인 실행 엔진 ──────────────────────────────────────────────
   155→class BrowserExecutor {
   156→  constructor() {
   157→    this.parser  = new FreeLangParser();
   158→    this.css     = new CSSCompiler();
   159→    this.js      = new JSCompiler();
   160→    this.html    = new HTMLCompiler();
   161→    this.history = [];
   162→  }
   163→
   164→  /**
   165→   * .free 코드 → { html, css, js, name, stats }
   166→   */
   167→  execute(freeCode) {
   168→    const start = Date.now();
   169→    const parsed = this.parser.parse(freeCode);
   170→
   171→    const css  = this.css.compile(parsed.style);
   172→    const js   = this.js.compile(parsed.script, parsed.name);
   173→    const html = this.html.compile(parsed.markup);
   174→
   175→    const result = {
   176→      name:  parsed.name,
   177→      html,  css, js,
   178→      props: parsed.props,
   179→      stats: {
   180→        parseMs:   Date.now() - start,
   181→        htmlBytes: html.length,
   182→        cssBytes:  css.length,
   183→        jsBytes:   js.length,
   184→        hasStyle:  css.length > 0,
   185→        hasScript: js.length > 0,
   186→      },
   187→    };
   188→
   189→    this.history.push({ code: freeCode, result, ts: Date.now() });
   190→    if (this.history.length > 50) this.history.shift();
   191→
   192→    return result;
   193→  }
   194→
   195→  /**
   196→   * 전체 미리보기 HTML 생성 (iframe srcdoc용)
   197→   */
   198→  buildPreviewHTML(result) {
   199→    return `<!DOCTYPE html>
   200→<html lang="ko">
   201→<head>
   202→<meta charset="UTF-8">
   203→<style>
   204→  * { box-sizing: border-box; margin: 0; padding: 0; }
   205→  body { font-family: system-ui, sans-serif; padding: 20px; background: #f8fafc; }
   206→  button { cursor: pointer; padding: 8px 16px; border: none; border-radius: 6px; font-size: 14px; }
   207→  button.primary   { background: #6366f1; color: #fff; }
   208→  button.secondary { background: #e2e8f0; color: #374151; }
   209→  button.ghost     { background: transparent; border: 1px solid #d1d5db; color: #374151; }
   210→  input { padding: 8px 12px; border: 1px solid #d1d5db; border-radius: 6px; font-size: 14px; width: 100%; }
   211→  .card { background: #fff; border-radius: 12px; padding: 20px; box-shadow: 0 2px 8px rgba(0,0,0,.08); }
   212→  .card.glass { background: rgba(255,255,255,.2); backdrop-filter: blur(10px); border: 1px solid rgba(255,255,255,.3); }
   213→  .container { display: flex; }
   214→  .container.column { flex-direction: column; }
   215→  .container.row    { flex-direction: row; }
   216→  .freewire-badge {
   217→    position: fixed; bottom: 8px; right: 8px;
   218→    background: #6366f1; color: #fff;
   219→    padding: 3px 8px; border-radius: 999px; font-size: 11px; opacity: .8;
   220→  }
   221→  ${result.css}
   222→</style>
   223→</head>
   224→<body>
   225→<div id="fw-root">${result.html || '<p style="color:#9ca3af">내용 없음</p>'}</div>
   226→<div class="freewire-badge">⚡ FreeWire</div>
   227→<script>${result.js}</script>
   228→</body>
   229→</html>`;
   230→  }
   231→
   232→  /** 마지막 실행 결과 */
   233→  lastResult() { return this.history[this.history.length - 1]?.result || null; }
   234→
   235→  /** 히스토리 초기화 */
   236→  clearHistory() { this.history = []; }
   237→}
   238→
   239→// ─── WASM Bridge 인터페이스 (미래 확장용) ───────────────────────
   240→const WASMBridge = {
   241→  _executor: new BrowserExecutor(),
   242→  _ready: true,
   243→
   244→  /** WASM 준비 여부 */
   245→  isReady() { return this._ready; },
   246→
   247→  /** .free 코드 컴파일 */
   248→  compile(freeCode) {
   249→    return this._executor.execute(freeCode);
   250→  },
   251→
   252→  /** 미리보기 HTML 생성 */
   253→  preview(freeCode) {
   254→    const result = this.compile(freeCode);
   255→    return this._executor.buildPreviewHTML(result);
   256→  },
   257→
   258→  /** 히스토리 */
   259→  history() { return this._executor.history; },
   260→};
   261→
   262→// Node.js / 브라우저 공용 export
   263→if (typeof module !== 'undefined') {
   264→  module.exports = { BrowserExecutor, WASMBridge, FreeLangParser, CSSCompiler, JSCompiler, HTMLCompiler };
   265→} else {
   266→  window.FreeWireWASM = WASMBridge;
   267→  window.BrowserExecutor = BrowserExecutor;
   268→}
